declare const __PWA__: boolean;

// The service worker (sw.js) is generated by vite-plugin-pwa for hosted builds only.
// Registered after load so it never competes with first paint.
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || typeof __PWA__ === 'undefined' || !__PWA__) return;
  if (!('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js', { scope: './' }).catch(() => {
      // Offline support is a progressive enhancement; the app works without it.
    });
  });
}
